 new ResizeObserver(()=>{if(active)renderPlan()}).observe(svg);
 return {activate(value){active=value;$('#plan-panel').hidden=!value;document.querySelector('.stage').classList.toggle('editing',value);if(value){if(!view)fit();refresh()}},refresh,select:choose,replace(l){const clean=upgradeLayout(l);persist(clean);onChange(clean);past.length=0;future.length=0;selected=null;dirty=false;fit();refresh()}};
